      }
      if (taskId) {
        const task = Number(taskId);
        if (!Number.isSafeInteger(task) || !completeTask.run(data.get('completed') === '1' ? 1 : 0, task, id).changes) {
          html(response, 404, page('<h1>Task not found</h1>'));
          return;
